INSERT INTO `agents` (`agent_id`, `agent_father_name`, `agent_address`, `national_id`, `account_type`, `contract_type`, `contract_date`, `contract_scan_file`, `image`, `account_no`, `account_status`, `description`, `note`, `user_id`, `province_id`, `created_at`, `updated_at`) VALUES
(1, 'مراد گیلدی', 'جوزجان، ولسوالی آقچه، پنجاه متره', '000', 'us dollar', 'carpet seller', '2026-07-27', '', 'uploads/agent-image/1785127264-AGENT-Image.png', 'AG-0001', 1, NULL, 'قیمت های جدید گبه جری کوالتی 30x30 - خورد متر تا شش متره فی متر 30 دالر و کلان متر تا 12 متره فی متر 33 دالر \r\nلیست قیمت های قاری حق مراد از تاریخ 9 فبروری 2026\r\n\r\n1-	تار یک کش صفری رسانده آقچه فی بندل 4.5 دالر \r\n2-	قیمت فی متر مربع قالین 30/30 یککش  صفری تا 6 متره مبلغ 30 دالر \r\n3-	قیمت فی متر مربع قالین 30/30 یککش صفری از 7.50 تا 12 متره  مبلغ 30  دالر \r\n4-	تار رنگه برای نقشه های بازاری به کوالتی 32/36 فی کیلو 5 دالر \r\n5-	قیمت فی متر مربع قالین های نقشه های بازاری به کوالتی 32/36 فی متر مربع 55 دالر – تمام سایز ها خورد و کلان و پرنت نقشه ها بدوش قاری حق مراد میباشد. استفاده تار ماشینی در تنسته و گیلم های ریشه رنگه در قسمت رنگ کردن  همه تار .\r\n6-	رنگ تار ماشنی بدوش شرکت و متباقی کار،سوخت و دیگر مصارف بدوش قاری حق مراد میباشد مبلغ فی کیلو تار ماشینی 2.30 دالر \r\n7-	قیمت گیلم ریشه رنگه در سایز های خورد 13 دالر  و سایز کلان 14 دالر .\r\n8-	قیمت شگی های مکمل بافت  در سایز های خورد و کلان مبلغ فی متر 30 دالر .\r\n9-	قیمت شگی های سفید برجسته در سایز های خورد و کلان مبلغ فی متر 28 دالر .\r\n10-	قیمت تار های شگی مبلغ فی کیلو 6 دالر  هیچ تغییر در آن نیست .\r\n11-	قیمت گیلم های اولمی  در سایز های خورد وکلان از تار مرینوس و ریشه پخته مبلغ فی متر 15 دالر .\r\n12-	قاشقایی نورمال برش  کوالتی 20*20 سایز های خورد و کلان مبلغ فی متر 30 دالر .\r\n13-	مواد رنگه قاشقایی برای 20*20 قاشقایی مبلغ فی کیلو 3.40 دالر \r\n14-	قالین های آزاد  قاری حق مراد  به کوالتی 30*35 الی 6 متره مبلغ فی متر 36 دالر .\r\n15-	قالین های آزاد  قاری حق مراد  به کوالتی 30*35 الی 7.5 الی 10 متره مبلغ فی متر 38 دالر.\r\n16-	قالین های آزاد  قاری حق مراد  به کوالتی 30*35 الی 12 متره مبلغ فی متر 41 دالر.\r\n17-	مواد مشهدی فیل پای  به کوالتی 30*30 سایز های خورد و کلان مبلغ فی متر 23 دالر \r\n18-	گیلم ریشه رنگه برجسته نقشه دارکوالتی 8*20 مواد چتم فراهی از طرف شرکت الی 6 متره مبلغ فی متر 14 دالر .\r\n19-	گیلم ریشه رنگه برجسته نقشه دار کوالتی 8*20 مواد چتم فراهی ازطرف شرکت کلان سایزمبلغ فی متر 16 دالر\r\n20-	قالین های ZN به کوالتی 20*20 سایز خورد و کلان مواد سفید بدون رنگ فی کیلو 4 دالر  و تنسته 2.3 دالر  قیمت فی متر 30 دالر .\r\n•	نوت : وزن نورمال قالین های ZN کوالتی 20*20 فی مترمربع 3.750 کیلو گرام  بناً قالین های ZN  باید وزن گردد در صورت که مواد اغز وزن نورمال آن بیشتر کارشده باشهد آنرا فی کیلو 4 دالر و به رسیدات قاری حق مراد رسانیده شود.\r\n21-	همه 20*20 ها فی متر مربع سایز خورد و کلان آن  فی متر 30 دالر .\r\n•	در رنگ تار ها فقط رنگ خشک از طرف شرکت برای قاری حق مراد داده میشود متباقی مصارف بدوش خود قاری حق مراد میباشد .\r\n22-	پلین و مدرن BIT کوالتی 25*25 نقشه های مدرن و پلین سایز های خورد و کلان مبلغ فی متر 33 دالر .\r\n23-	نقشه های اوشاک کوالتی 25*25 سایز های خورد و کلان آن که مواد آن 6 دالر بوده فی متر 44 دالر .\r\n•	همچنان در صورت که برای دیگر نقشه ها گیلم ها قاری حق مراد مواد رنگ میکند مثل همین مصارف رنگ کردن بدوش قاری حق مراد میباشد و صرف رنگ خشک از طرف شرکت.\r\n24-	قزاق های مودیم  کوالتی 30*30 الی سایز 6 متره فی متر مربع 34 دالر .\r\n25-	قزاق های مودیم  کوالتی 30*30 الی سایز 7.5 متره به بالا فی متر مربع 36 دالر .\r\n26-	تار ماشینی برای مودیم قزاق  فی بندل 10 دالر .\r\n27-	قالین های بازاری کوالتی 32*36 الی 6 متره فی متر مربع مبلغ 45 دالر مواد از اصلی دست ریس از طرف قاری حق مراد.\r\n28-	قالین های مودیم کوالتی 32*36 نقشه بازاری فی متر 36 دالر تا 6 متره کلان سایز فی متر 39 دالر و مواد آن فی بندل 10 دالر رنگ از طرف شرکت.\r\n29-	قالین های چین کوالتی  30*30  تمام سایز ها خورد و کلان  برش آن 2 سانتی  فی متر 32 دالر .\r\n30-	قیمت تار های رنگه برای نقشه های چین فی کیلو 2.30 دالر .\r\n31-	گبه های جدید 25*25 دبل برش 2 سانتی  الی 6 متره  فی متر 43 دالر و کلان سایز آن 45 دالر  و مواد آن فی کیلو 4 دالر .\r\n32-	نقشه های بوستان  کوالتی 17*17 دبل برش نورمال آقچه – فی متر مربع خورد و کلان سایز 13 دالر اجوره.\r\n33-	نقشه های بامیان کوالتی 32*32 خورد سایز و کلان سایز  الی 6 متره  فی متر مربع  43 دالر .\r\n\r\n34- گبه های ایرانی قاری حق مراد به حساب اجوره یی است فی متر 1400 و 1500 شش متره آن\r\n35- نقشه سرخ و موری گل پروگرام تولیدی کوالتی 30/30 سایز الی 6 متره 28  دالر \r\n36- نقشه سرخ و موری گل پروگرام تولیدی کوالتی 30/30 سایز از 6 متره بالا کلان متر فی متر 30 دالر', 4, 5, '2026-07-27 09:11:04', '2026-09-08 17:57:16'),
